import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, jobFromRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row can only be left behind when the worker was interrupted. Make it eligible
// immediately and undo the interrupted start so recovery resumes that attempt.
db.prepare("UPDATE jobs SET status='queued',attempts=MAX(attempts-1,0),progress_completed=0,available_at=0,updated_at=? WHERE status='running'").run(new Date().toISOString());
console.log('worker started');

function heartbeat(): void {
  db.prepare('INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
}
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 1000);
heartbeatTimer.unref();
function takeJob(): ReturnType<typeof jobFromRow> | null {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as Record<string,unknown>|undefined;
    if (!row) { db.exec('COMMIT'); return null; }
    if (Number(row.attempts) >= 3) {
      db.prepare("UPDATE jobs SET status='failed',error='transient failure',result=NULL,updated_at=? WHERE id=? AND status='queued'").run(new Date().toISOString(),String(row.id));
      db.exec('COMMIT'); return null;
    }
    const now = new Date().toISOString();
    const id = String(row.id);
    db.prepare("UPDATE jobs SET status='running',attempts=attempts+1,progress_completed=0,result=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'").run(now,id);
    const updated = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string,unknown>;
    db.exec('COMMIT'); return jobFromRow(updated);
  } catch (error) { db.exec('ROLLBACK'); throw error; }
}

async function processJob(job: NonNullable<ReturnType<typeof takeJob>>): Promise<void> {
  const updateProgress = db.prepare("UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'");
  const finish = db.prepare("UPDATE jobs SET status='completed',result=?,progress_completed=?,updated_at=? WHERE id=? AND status='running'");
  const fail = db.prepare("UPDATE jobs SET status=?,available_at=?,error=?,result=NULL,updated_at=? WHERE id=? AND status='running'");
  if (job.attempts <= job.failAttempts) {
    // Fail before the first step, as the simulated dependency does.
    const now = new Date().toISOString();
    if (job.attempts >= 3) fail.run('failed',0,'transient failure',now,job.id);
    else fail.run('queued',Date.now()+500,null,now,job.id);
    return;
  }
  for (let completed = 1; completed <= job.steps; completed++) {
    if (stopping) return; // Leave running state for recovery by the next worker.
    await sleep(100);
    if (stopping) return;
    updateProgress.run(completed,new Date().toISOString(),job.id);
  }
  finish.run(JSON.stringify({output:job.input.toUpperCase()}),job.steps,new Date().toISOString(),job.id);
}

try {
  while (!stopping) {
    heartbeat();
    const job = takeJob();
    if (job) await processJob(job);
    else await sleep(200);
  }
} finally {
  clearInterval(heartbeatTimer);
  // If SIGTERM interrupted active work, return it to the queue without consuming an attempt.
  db.prepare("UPDATE jobs SET status='queued',attempts=MAX(attempts-1,0),progress_completed=0,available_at=0,updated_at=? WHERE status='running'").run(new Date().toISOString());
  // Expire immediately so a stopped process is not reported as alive.
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}

